<script lang="ts">
 import {onMount} from 'svelte';import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';
 import {engineToken,restoreEngineSession,engineAPI,followEngineLogs} from '$lib/engine/client';
 import {bytes,validImage,validDomain,validProjectName} from '$lib/engine/stream.js';
 import type {Health,ServerInfo,ReadinessCheck,EngineProject,EngineJob,EngineRelease,EngineLog} from '$lib/engine/types';
 let health:Health|null=null,server:ServerInfo|null=null,checks:ReadinessCheck[]=[],projects:EngineProject[]=[],jobs:EngineJob[]=[],releases:EngineRelease[]=[];
 let password='',name='',image='nginx:alpine',port=80,domain='',https=true,editing='',nextImage='',selected='',logLines:EngineLog[]=[],lastJob='',error='',notice='',loading=true,busy=false,streaming=false;
 let logsController:AbortController|null=null;let timer:ReturnType<typeof setInterval>|null=null;let disposed=false;
 $: target=projects.find(p=>p.id===selected);$: projectJobs=jobs.filter(j=>j.project_id===selected);$: projectReleases=releases.filter(r=>r.project_id===selected);
 async function probe(){try{health=await engineAPI.health();error='';}catch(e){health=null;error=e instanceof Error?e.message:'Engine not available.';}finally{loading=false;}}
 async function refresh(){try{const [srv,ready,ps,js,rs]=await Promise.all([engineAPI.server(),engineAPI.readiness(),engineAPI.projects(),engineAPI.jobs(),engineAPI.releases()]);if(disposed)return;server=srv;checks=ready.checks;projects=ps.projects||[];jobs=js.jobs||[];releases=rs.releases||[];if(selected&&!projects.some(p=>p.id===selected)){selected='';stopLogs();}}catch(e){if(!disposed){error=e instanceof Error?e.message:'Could not load engine state.';if(error.includes('authenticated')||error.includes('401')){server=null;}}}}
 onMount(()=>{restoreEngineSession();void probe().then(()=>{if($engineToken)void refresh();});timer=setInterval(()=>{if($engineToken&&health)void refresh();},3000);return ()=>{disposed=true;if(timer)clearInterval(timer);stopLogs();};});
 async function signin(){if(!password)return;busy=true;try{await engineAPI.login(password);password='';error='';notice='Signed in to the local engine.';await refresh();}catch(e){error=e instanceof Error?e.message:'Login failed.';}finally{busy=false;}}
 async function signout(){stopLogs();try{await engineAPI.logout();notice='Signed out. Engine session revoked.';}catch{notice='Local session cleared; engine revocation could not be confirmed.';}finally{server=null;checks=[];projects=[];jobs=[];releases=[];selected='';}}
 async function action(fn:()=>Promise<{job:EngineJob}>,label:string){busy=true;error='';try{const {job}=await fn();lastJob=job.id;notice=label+' queued (job '+job.id+'). Follow its status below.';await refresh();}catch(e){error=e instanceof Error?e.message:'Operation failed.';}finally{busy=false;}}
 async function deploy(){if(!validProjectName(name.trim())||!validImage(image)||!validDomain(domain.trim())||port<1||port>65535){error='Review the project name, image, domain and container port.';return;}const data={name:name.trim(),image:image.trim(),port,domain:domain.trim()||undefined,https};await action(()=>engineAPI.deploy(data),'Deployment');}
 async function redeploy(p:EngineProject){if(!validImage(nextImage)){error='Enter a valid container image.';return;}await action(()=>engineAPI.redeploy(p.id,nextImage.trim()),'Redeployment');editing='';}
 async function rollback(p:EngineProject){if(!window.confirm('Create a rollback job for '+p.name+'?'))return;await action(()=>engineAPI.rollback(p.id),'Rollback');}
 async function restart(p:EngineProject){if(!window.confirm('Restart '+p.name+'?'))return;await action(()=>engineAPI.restart(p.id),'Restart');}
 function stopLogs(){logsController?.abort();logsController=null;streaming=false;}
 async function showLogs(p:EngineProject){stopLogs();selected=p.id;logLines=[];const ctrl=new AbortController();logsController=ctrl;streaming=true;try{await followEngineLogs(p.id,(line)=>{if(!ctrl.signal.aborted)logLines=[...logLines.slice(-249),line];},ctrl.signal);}catch(e){if(!ctrl.signal.aborted)error=e instanceof Error?e.message:'Log stream failed.';}finally{if(logsController===ctrl){logsController=null;streaming=false;}}}
</script>
<Heading title="Engine" subtitle="Actual server management API · separate from the browser demo workspace"><button class="btn secondary" on:click={()=>{void probe();if($engineToken)void refresh();}}>Refresh connection</button></Heading>
<div class="stack"><div class="callout"><strong>Engine and demo workspace are separate.</strong><p>This page reads from the Go service at <code>/api/v1</code>. Other prototype modules remain local simulations until explicitly migrated. An engine in mock mode does not create containers or obtain HTTPS certificates.</p></div>
{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="subtitle" role="status">{notice}</p>{/if}
<section class="card stack"><div class="row between wrap"><div><h3>Engine connection</h3><p class="subtitle">{loading?'Checking…':health?'API reachable · version '+health.version:'Engine not connected'}</p></div><span class={'pill '+(health?(health.mock_mode?'warning':'success'):'warning')}>{health?(health.mock_mode?'MOCK MODE':'LIVE ENGINE'):'OFFLINE'}</span></div>
{#if health&&!$engineToken}<form class="native-inline" on:submit|preventDefault={signin}><label class="field grow">Administrator password<input type="password" bind:value={password} autocomplete="current-password" required/></label><button class="btn primary" style="align-self:end" type="submit" disabled={busy}>Sign in</button></form>{:else if $engineToken}<div class="row between wrap"><p class="subtitle">Signed in · session token stored in this browser tab only</p><button class="btn secondary small" on:click={signout}>Sign out</button></div>{/if}
</section>
{#if health&&$engineToken}
{#if server}<div class="grid3"><section class="card"><h3>VPS host</h3><strong>{server.hostname}</strong><p class="subtitle">{server.os} · {server.arch} · {server.cpu_cores} CPU cores</p></section><section class="card"><h3>Memory</h3><strong>{bytes(server.mem_total)}</strong><p class="subtitle">Discovered system memory</p></section><section class="card"><h3>Disk</h3><strong>{bytes(server.disk_total-server.disk_used)} free</strong><p class="subtitle">of {bytes(server.disk_total)} total</p></section></div>{/if}
<section class="card stack"><h3>Server readiness</h3>{#each checks as c}<div class="setting-row"><div><strong>{c.label}</strong><small style="display:block">{c.detail}</small></div><span class={'pill '+(c.ok?'success':'warning')}>{c.ok?'Passed':'Action needed'}</span></div>{:else}<p class="subtitle">No readiness checks returned.</p>{/each}</section>
<section class="card stack"><div><h3>Deploy container image</h3><p class="subtitle">A queued Go job handles pull, health checks and routing. Real deployment must only be used on a disposable test VPS after server hardening.</p></div><form class="stack" on:submit|preventDefault={deploy}><div class="grid2"><label class="field">Project name<input bind:value={name} placeholder="hello-world" required/></label><label class="field">Container image<input bind:value={image} placeholder="nginx:alpine" required/></label><label class="field">Internal port<input type="number" min="1" max="65535" bind:value={port}/></label><label class="field">Domain (optional)<input bind:value={domain} placeholder="app.example.com"/></label></div><label class="check"><input type="checkbox" bind:checked={https}/> Request HTTPS if a domain is supplied</label><div><button class="btn primary" type="submit" disabled={busy}>{busy?'Submitting…':'Deploy image'}</button></div></form></section>
<section class="card table-card"><div class="table-head"><h3>Engine-managed applications</h3><p class="subtitle">Unlike the demo projects, these records come from the Go engine.</p></div><div class="table-wrap"><table><thead><tr><th>Project</th><th>Image</th><th>Status</th><th>Actions</th></tr></thead><tbody>{#each projects as p (p.id)}<tr><td><button class="link-btn" on:click={()=>{selected=p.id;stopLogs();}}>{p.name}</button><small>{p.domain||'No custom domain'}</small></td><td class="mono native-path">{p.image}</td><td><span class="pill">{p.status}</span></td><td><div class="table-actions"><button class="btn secondary small" on:click={()=>{selected=p.id;editing=p.id;nextImage=p.image;stopLogs();}}>New release</button><button class="btn secondary small" on:click={()=>{void showLogs(p);}}>Logs</button><button class="btn secondary small" disabled={busy||!p.current_release} on:click={()=>rollback(p)}>Roll back</button><button class="btn secondary small" disabled={busy||p.status!=='running'} on:click={()=>restart(p)}>Restart</button></div></td></tr>{:else}<tr><td colspan="4">No applications deployed by this engine.</td></tr>{/each}</tbody></table></div></section>
{#if editing&&target&&editing===selected}<form class="card stack" on:submit|preventDefault={()=>redeploy(target)}><h3>Deploy another image for {target.name}</h3><label class="field">Image reference<input bind:value={nextImage} required/></label><div class="row wrap"><button class="btn primary" type="submit" disabled={busy}>Queue new release</button><button class="btn secondary" type="button" on:click={()=>editing=''}>Cancel</button></div></form>{/if}
{#if selected&&target}<section class="card stack"><div class="row between wrap"><h3>{target.name} · logs and releases</h3><div class="row wrap"><button class="btn secondary small" on:click={()=>{void showLogs(target);}}>{streaming?'Restart stream':'Stream logs'}</button><button class="btn secondary small" on:click={stopLogs}>Stop stream</button></div></div>{#if logLines.length}<pre class="native-log mono">{logLines.map(l=>'['+l.stream+'] '+l.message).join('')}</pre>{:else}<p class="subtitle">Select Logs to start the authenticated stream.</p>{/if}<div class="table-wrap"><table><thead><tr><th>Release</th><th>Image</th><th>Status</th></tr></thead><tbody>{#each projectReleases.slice().reverse() as r}<tr><td class="mono">{r.id.slice(0,8)}</td><td class="mono native-path">{r.image}:{r.tag}</td><td><span class="pill">{r.status}</span></td></tr>{:else}<tr><td colspan="3">No releases recorded yet.</td></tr>{/each}</tbody></table></div></section>{/if}
<section class="card table-card"><div class="table-head"><h3>Deployment jobs</h3><p class="subtitle">{lastJob?'Last queued job: '+lastJob:'Job status updates from the engine'}</p></div><div class="table-wrap"><table><thead><tr><th>Job</th><th>Kind</th><th>Status</th><th>Latest progress</th></tr></thead><tbody>{#each jobs.slice().reverse().slice(0,25) as j}<tr><td class="mono">{j.id.slice(0,8)}</td><td>{j.kind}</td><td><span class="pill">{j.status}</span></td><td>{j.error||j.log?.at(-1)?.message||'Queued'}</td></tr>{:else}<tr><td colspan="4">No engine jobs yet.</td></tr>{/each}</tbody></table></div></section>
{/if}</div>
